def scan_forbidden_in_sources(root: Path, allow_root_env: bool) -> list[str]:
    """Проверка только тех путей, которые попадут в ZIP."""
    hits: list[str] = []

    def check_file(path: Path) -> None:
        rel = path.relative_to(root)
        if rel.name in FORBIDDEN_NAMES:
            hits.append(str(rel))
            return
        if any(rel.name.endswith(suf) for suf in FORBIDDEN_SUFFIXES):
            hits.append(str(rel))
            return
        if _is_forbidden(rel):
            hits.append(str(rel))

    if not allow_root_env:
        for name in FORBIDDEN_NAMES:
            p = root / name
            if p.is_file():
                hits.append(name)
        for p in root.glob("*.session*"):
            if p.is_file():
                hits.append(p.name)

    for name in INCLUDE_DIRS:
        base = root / name
        if not base.is_dir():
            hits.append(f"нет каталога: {name}")
            continue
        for path in base.rglob("*"):
            if path.is_file():
                check_file(path)

    for name in INCLUDE_FILES:
        path = root / name
        if path.is_file():
            check_file(path)

    for name in INCLUDE_SCRIPTS + INCLUDE_DEPLOY + INCLUDE_DOCS:
        for parent in (root / "scripts", root / "deploy", root / "docs"):
            path = parent / name
            if path.is_file():
                check_file(path)

    return hits

